// View-model for the validation blocks (home, methodology). Every figure is read from src/data/validation.json (generated by
// scripts/sync-validation.mjs from eval/validation.json) and only formatted here; nothing is typed by hand.

export interface Interval {
  effect_pp: number;
  ci_low_pp: number;
  ci_high_pp: number;
}
export interface SignalRow {
  signal: string;
  status: string;
  post_award_information: boolean;
  circular: boolean;
  n_with: number;
  n_without: number;
  adjusted: (Interval & { p_value: number; p_holm?: number | null }) | null;
}
export interface CompositeRow {
  label: string;
  n: number;
  spearman: { rho: number; ci_low: number; ci_high: number } | null;
  effect_per_10_points_pp: Interval | null;
}
export interface PeriodData {
  years: number[];
  n_processes: number;
  n_buyers: number;
  median_saving: number;
  signals: SignalRow[];
  composites: CompositeRow[];
}
export interface PooledThreshold {
  threshold_code: string;
  category: string;
  years: number[];
  budget: {
    status: string;
    n_window: number;
    observed_below?: number;
    expected_below?: number;
    observed_above?: number;
    expected_above?: number;
    excess_bins?: number;
    excess_bins_ci?: [number, number];
    excess_pct?: number;
    excess_pct_ci?: [number, number];
    missing_above_pct?: number;
  };
}
export interface ValidationData {
  sample: number;
  min_flagged: number;
  min_buyers: number;
  explore: PeriodData;
  confirm: PeriodData;
  list_test: {
    official_list_size: number | null;
    larger_list_obtained: boolean | null;
    checked_on: string | null;
    n_positives: number;
    n_unlabelled: number;
    auc: { estimate: number; low: number; high: number };
    se_null: number | null;
    detectable_auc: number | null;
  };
  thresholds: {
    verified_years: number[];
    excluded_years: Record<string, string>;
    pooled: PooledThreshold[];
  };
}

const LOCALE = "es-EC";
const nf = (min: number, max = min) => new Intl.NumberFormat(LOCALE, { minimumFractionDigits: min, maximumFractionDigits: max });
const int = nf(0);
const d1 = nf(1);
const d2 = nf(2);
const d3 = nf(3);
const signed1 = new Intl.NumberFormat(LOCALE, { minimumFractionDigits: 1, maximumFractionDigits: 1, signDisplay: "exceptZero" });

/** Real minus sign (U+2212) instead of a hyphen, so a screen reader says "menos". */
const minus = (s: string) => s.replace("-", "−");

export const fmtCount = (n: number) => int.format(n);
/** Percentage points, one decimal, absolute value (for prose such as "8,3 puntos menos"). */
export const fmtPpAbs = (v: number) => d1.format(Math.abs(v));
/** Percentage points, one decimal, signed. */
export const fmtPpSigned = (v: number) => minus(signed1.format(v));
export const fmtDec2 = (v: number) => d2.format(v);
export const fmtDec3 = (v: number) => d3.format(v);
export const fmtDec1 = (v: number) => d1.format(v);
export const fmtPpRange = (a: Interval) => `${fmtPpSigned(a.ci_low_pp)} a ${fmtPpSigned(a.ci_high_pp)}`;

/** Labels as the API's /signals endpoint gives them (kept here because the chart and the tables need them without a request). */
export const SIGNAL_LABEL: Record<string, string> = {
  SINGLE_BIDDER: "Oferente único",
  SHORT_TENDER_WINDOW: "Plazo de ofertas atípicamente corto",
  NEW_SUPPLIER: "Proveedor de reciente creación",
  RECURRING_COBIDDERS: "Oferentes que coinciden repetidamente",
  SUPPLIER_NOT_ACTIVE: "Proveedor no activo en el SRI",
  GHOST_COMPANY_LIST: "Proveedor ya incluido en el listado del SRI al momento del proceso",
  LOW_SAVING: "Ahorro atípicamente bajo",
  CONTRACT_VS_COMPANY_SIZE: "Contrato desproporcionado frente a los ingresos de la empresa",
  BUYER_CONCENTRATION: "Concentración de adjudicaciones en un proveedor",
};
/** Short labels for the chart axis. */
export const SIGNAL_SHORT: Record<string, string> = {
  SINGLE_BIDDER: "Un solo oferente",
  SHORT_TENDER_WINDOW: "Plazo de ofertas corto",
  NEW_SUPPLIER: "Proveedor nuevo",
  RECURRING_COBIDDERS: "Oferentes que coinciden",
};

export type Verdict = "lower" | "none" | "higher" | "untestable";
export const verdictOf = (s: SignalRow): Verdict => {
  if (s.status !== "tested" || !s.adjusted) return "untestable";
  if (s.adjusted.ci_high_pp < 0) return "lower";
  if (s.adjusted.ci_low_pp > 0) return "higher";
  return "none";
};

export const primary = (p: PeriodData) => p.signals.filter((s) => !s.circular);
export const circular = (p: PeriodData) => p.signals.filter((s) => s.circular);
const bySignal = (p: PeriodData, code: string) => p.signals.find((s) => s.signal === code);

const WITHOUT_CIRCULAR = "production weights without the circular signals";
export const compositeWithoutCircular = (p: PeriodData) => p.composites.find((c) => c.label === WITHOUT_CIRCULAR) ?? null;

/** Everything the home block and the methodology section print, already formatted. Throws never; a missing piece is null. */
export function buildFigures(d: ValidationData) {
  const t = d.list_test;
  const single = bySignal(d.confirm, "SINGLE_BIDDER")?.adjusted ?? null;
  const short = bySignal(d.confirm, "SHORT_TENDER_WINDOW")?.adjusted ?? null;
  const fresh = bySignal(d.confirm, "NEW_SUPPLIER")?.adjusted ?? null;
  const recurring = bySignal(d.confirm, "RECURRING_COBIDDERS");
  const comp = compositeWithoutCircular(d.confirm);
  const confirmPrimary = primary(d.confirm);
  const untestable = confirmPrimary.filter((s) => s.status !== "tested").map((s) => s.signal);
  return {
    list: {
      official: t.official_list_size != null ? fmtCount(t.official_list_size) : null,
      positives: fmtCount(t.n_positives),
      unlabelled: fmtCount(t.n_unlabelled),
      auc: fmtDec3(t.auc.estimate),
      aucLow: fmtDec3(t.auc.low),
      aucHigh: fmtDec3(t.auc.high),
      includesHalf: t.auc.low <= 0.5 && t.auc.high >= 0.5,
      detectable: t.detectable_auc != null ? fmtDec2(t.detectable_auc) : null,
      seNull: t.se_null != null ? fmtDec3(t.se_null) : null,
      checkedOn: t.checked_on,
    },
    confirm: {
      years: `${d.confirm.years[0]}–${d.confirm.years[1]}`,
      n: fmtCount(d.confirm.n_processes),
      buyers: fmtCount(d.confirm.n_buyers),
      single: single && fmtPpAbs(single.effect_pp),
      singleRange: single && `${fmtPpAbs(single.ci_high_pp)} a ${fmtPpAbs(single.ci_low_pp)}`,
      short: short && fmtPpAbs(short.effect_pp),
      fresh: fresh && fmtPpAbs(fresh.effect_pp),
      recurringNone: recurring ? verdictOf(recurring) === "none" : false,
      untestableCount: untestable.length,
      circularCount: circular(d.confirm).length,
      composite:
        comp?.spearman && comp.effect_per_10_points_pp
          ? {
              rho: fmtDec2(comp.spearman.rho),
              rhoAbs: fmtDec2(Math.abs(comp.spearman.rho)),
              per10: fmtPpAbs(comp.effect_per_10_points_pp.effect_pp),
            }
          : null,
    },
    explore: { years: `${d.explore.years[0]}–${d.explore.years[1]}`, n: fmtCount(d.explore.n_processes) },
  };
}

export type Figures = ReturnType<typeof buildFigures>;

/** Rows of the forest plot: one per tested primary signal in the confirmation period, with its interval. */
export function forestRows(d: ValidationData) {
  return primary(d.confirm)
    .filter((s) => verdictOf(s) !== "untestable")
    .map((s) => ({ code: s.signal, label: SIGNAL_SHORT[s.signal] ?? SIGNAL_LABEL[s.signal] ?? s.signal, verdict: verdictOf(s), ...s.adjusted! }));
}
